/*
  0005_hse_codes — the 6836 HSE codes of old DigiDocs (M_HSECode) with their import duty, levy, excise
  and VAT rates (%) and the tariff period they were entered for (2022). Inserted in batches of
  1,000 rows (the most one INSERT … VALUES accepts).

  Run against DigiDocsOPNext after 0004 (see database/README.md):
      sqlcmd -S <server> -d DigiDocsOPNext -E -b -i database/migrations/0005_hse_codes.sql

  Safe to run twice: it records itself in dbo.schema_migrations and stops if already applied.
  Never edit this file after it has been applied anywhere; add a new one instead.
  Generated from the old DigiDocs dump (Database/digidocs-09Mar26.sql); legacy_id is the old id.
*/
-- sqlcmd starts with QUOTED_IDENTIFIER OFF; filtered indexes need it ON (SSMS sets it by default).
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET XACT_ABORT ON;
SET NOCOUNT ON;

BEGIN TRANSACTION;

IF EXISTS (SELECT 1 FROM dbo.schema_migrations WHERE migration_id = '0005')
BEGIN
    PRINT '0005_hse_codes is already applied. Nothing to do.';
    COMMIT TRANSACTION;
    RETURN;
END;









COMMIT TRANSACTION;
PRINT '0005_hse_codes applied: 6836 HSE codes.';
